#!/usr/bin/env node
/**
 * Build Gatekeeper — Report Renderer
 *
 * Turns run-build-gate.js's own JSON result straight into docs/agent_output/05-test-gate/build_<id>.md.
 * No agent writes anything into this pipeline — this is the one report in the whole system that
 * is 100% machine-generated, end to end.
 *
 * Usage:
 *   node scripts/render-build-report.js --all
 *   node scripts/render-build-report.js --story JIRA-001
 */
const fs = require('fs');
const path = require('path');
const {
  OUT_DIR, OUT_README, rel, listStep2Changes, resultPathFor, reportPathFor,
} = require('./lib/gate');

function statusOf(result) {
  if (result.refused) return 'Refused';
  return result.passed ? 'Passed' : 'Failed';
}

function render(id, title, result) {
  const out = [];
  out.push(`# Build Gate — ${id}`);
  out.push('');
  out.push(`## ${title}`);
  out.push('');
  out.push(`_Generated by scripts/render-build-report.js on ${new Date().toISOString().slice(0, 10)}. Gate run ${result.generatedAt || 'not recorded'}. Every line below comes straight from the gate script — nothing here is agent-written._`);
  out.push('');

  const status = statusOf(result);
  out.push('## At a glance', '');
  out.push('| | |', '|---|---|');
  out.push(`| **Status** | ${status} |`);
  const dep = result.dependencyCheck;
  out.push(`| **Dependency changes detected** | ${dep && (dep.added.length || dep.removed.length) ? '**yes**' : 'no'} |`);
  out.push('');

  out.push('## 1. Build result', '');
  if (result.refused) {
    out.push(`**Refused.** ${result.reason}`);
  } else if (!result.steps) {
    out.push(`Stopped at stage \`${result.stage}\` before the build ran.`, '', '```', result.output, '```');
  } else {
    out.push('| Command | Exit code |', '|---|---|');
    for (const s of result.steps) out.push(`| \`${s.command}\` | ${s.exitCode} |`);
    out.push('');
    out.push('<details><summary>Full output</summary>', '');
    for (const s of result.steps) { out.push('```', s.output, '```', ''); }
    out.push('</details>');
  }
  out.push('');

  out.push('## 2. Dependency tree diff', '');
  out.push('_Compares `mvn dependency:tree` captured before and after the change is applied, in the '
    + 'same worktree — flags any dependency version the change pulled in or removed that its plan '
    + 'did not call for._', '');
  if (!dep) {
    out.push('_Not measured (build stopped before this stage)._');
  } else if (!dep.added.length && !dep.removed.length) {
    out.push('No dependency changes.');
  } else {
    if (dep.added.length) { out.push('Added:'); dep.added.forEach((l) => out.push(`- \`${l}\``)); }
    if (dep.removed.length) { out.push('Removed:'); dep.removed.forEach((l) => out.push(`- \`${l}\``)); }
  }
  out.push('');

  out.push('---', '', 'Run inside an isolated `git worktree` — applied and removed, the real working tree was never touched.', '');
  return out.join('\n');
}

const INDEX_MARKER = '<!-- AUTO-GENERATED TABLE — regenerated by 05_additional-test-execution (QA + build), do not hand-edit below this line -->';

function testGateReadmeContract() {
  return `# Step 05 — QA + Build Gate

Two fully deterministic gates run against every change in
[\`docs/agent_output/03-development/\`](../03-development/) whose Status is \`Compiled\` or
\`Compile Failed\`, both by \`05_additional-test-execution\`.

`;
}

function rewriteIndex() {
  if (!fs.existsSync(OUT_DIR)) return;
  const ids = new Set();
  for (const f of fs.readdirSync(OUT_DIR)) {
    const m = /^(?:qa|build)_(.+)\.md$/i.exec(f);
    if (m) ids.add(m[1]);
  }
  const rows = [...ids].sort((a, b) => a.localeCompare(b, undefined, { numeric: true })).map((id) => {
    const qaFile = path.join(OUT_DIR, `qa_${id}.md`);
    const buildFile = path.join(OUT_DIR, `build_${id}.md`);
    const qaText = fs.existsSync(qaFile) ? fs.readFileSync(qaFile, 'utf8') : null;
    const buildText = fs.existsSync(buildFile) ? fs.readFileSync(buildFile, 'utf8') : null;
    const titleMatch = (qaText && /^##\s+(.+)$/m.exec(qaText)) || (buildText && /^##\s+(.+)$/m.exec(buildText));
    const qaStatusMatch = qaText && /\|\s*\*\*Status\*\*\s*\|\s*([^|]+)\|/.exec(qaText);
    const buildStatusMatch = buildText && /\|\s*\*\*Status\*\*\s*\|\s*([^|]+)\|/.exec(buildText);
    return {
      id,
      title: titleMatch ? titleMatch[1].trim() : '(untitled)',
      qaStatus: qaText ? (qaStatusMatch ? qaStatusMatch[1].trim() : 'unknown') : '_pending_',
      buildStatus: buildText ? (buildStatusMatch ? buildStatusMatch[1].trim() : 'unknown') : '_pending_',
    };
  });
  const existing = fs.existsSync(OUT_README) ? fs.readFileSync(OUT_README, 'utf8') : testGateReadmeContract();
  const contract = existing.includes(INDEX_MARKER) ? existing.slice(0, existing.indexOf(INDEX_MARKER)) : existing.trimEnd() + '\n\n';
  const table = [INDEX_MARKER, ''];
  if (!rows.length) table.push('_No Step 05 reports yet._', '');
  else {
    table.push('| Story | Title | QA | Build |', '|---|---|---|---|');
    for (const r of rows) table.push(`| ${r.id} | ${r.title} | ${r.qaStatus} | ${r.buildStatus} |`);
    table.push('');
  }
  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(OUT_README, contract.trimEnd() + '\n\n' + table.join('\n'));
}

function renderOne(id) {
  const change = listStep2Changes().find((c) => c.id.toLowerCase() === id.toLowerCase());
  if (!change) throw new Error(`No change "${id}" with a captured diff.`);
  const rf = resultPathFor(id);
  if (!fs.existsSync(rf)) throw new Error(`No gate result at ${rel(rf)}. Run run-build-gate.js --story ${id} first.`);
  const result = JSON.parse(fs.readFileSync(rf, 'utf8'));

  const target = reportPathFor(id);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, render(id, change.title, result));
  return { id, status: statusOf(result), report: rel(target) };
}

function main() {
  const argv = process.argv.slice(2);
  const all = argv.includes('--all') || argv.includes('-a');
  const storyIdx = argv.findIndex((a) => a === '--story' || a === '-s');

  if (all) {
    const targets = listStep2Changes();
    const written = []; const skipped = [];
    for (const t of targets) {
      try { const r = renderOne(t.id); written.push(r); console.log(`${r.id.padEnd(10)} ${r.status.padEnd(10)} -> ${r.report}`); } catch (err) { skipped.push(t.id); console.error(`${t.id.padEnd(10)} SKIPPED  ${err.message.split('\n')[0]}`); }
    }
    rewriteIndex();
    console.log(`\nWrote ${written.length}/${targets.length} report(s).`);
    if (skipped.length) process.exitCode = 1;
    return;
  }
  if (storyIdx === -1) throw new Error('Missing --story or --all.');
  const r = renderOne(argv[storyIdx + 1]);
  rewriteIndex();
  console.log(`Build Gatekeeper — wrote ${r.report} (${r.status})`);
}

try { main(); } catch (err) { console.error('Rendering failed:', err.message); process.exit(1); }
